        "al-sanawiyya": "the annual",
        "anna": "that",
        "al-sunduuq": "the fund",
        "ahraza": "achieved, made",
        "taqaddaman": "progress",
        "kabiiran": "great",
        "barnaamij": "programme",
        "laakin": "but",
        "laa": "not",
        "yazaalu": "ceases (laa yazaalu = still)",
